// 定义时间线事件的数据模型import 'package:auto_shop_server/app/utils/global.dart';import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';List colors = [Colors.grey[300], Colors.green, Colors.red];List titleStyles = [greyStyle(), greenBoldStyle(), redBoldStyle()];List descStyles = [greyStyle(), greenStyle(), redStyle()];class TimelineEvent {  final String title;  final String? time;  final String? description;  final int? status; // 0、1、2 默认=0  TimelineEvent({required this.title, this.time="", this.description="", this.status=0});}class TimelineView extends StatelessWidget {  final List<TimelineEvent> items;  const TimelineView({super.key, required this.items});  @override  Widget build(BuildContext context) {    return Container(      padding: const EdgeInsets.fromLTRB(20, 0, 10, 0).r,      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        mainAxisAlignment: MainAxisAlignment.start,        children: [          _buildSection(),        ],      ),    );  }  //  Widget _buildSection() {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        Column(          crossAxisAlignment: CrossAxisAlignment.start,          children: items.asMap().entries.map((entry) {            int index = entry.key;            return _buildGroup(index, index + 1);          }).toList(),        ),      ],    );  }  // 构建带序号  Widget _buildGroup(int index, int number) {    return Stack(      children: [        // 调整竖线的位置        if (index != items.length - 1) Positioned(          left: 10.h, // top: index == 1 ? 20 : 0,          top: 32.h / 2,          bottom: 0,          child: Container(width: 1.w, color: Colors.grey),        ),        Column(          crossAxisAlignment: CrossAxisAlignment.start,          mainAxisSize: MainAxisSize.min,          children: [            _sectionTitle(items[index]),            _buildSections(items[index]),          ],        ),      ],    );  }  // 审批小组成员  _buildSections(TimelineEvent item) {    return Padding(      padding: const EdgeInsets.fromLTRB(30, 0, 0, 16).r,      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          if (item.status == 2 && item.description!.isNotEmpty)            Text(item.description!, style: TextStyle(fontSize: 12.sp, color: Colors.black)),          if (item.status == 2 && item.description!.isNotEmpty)            SizedBox(height: 6.r),          if (item.time!.isNotEmpty)            Text(item.time!, style: TextStyle(fontSize: 12.sp, color: Colors.grey)),        ],      ),    );  }  // 标题  _sectionTitle(TimelineEvent item) {    return Container(      padding: EdgeInsets.fromLTRB(0, 0, 0, 0).r,      child: Row(        crossAxisAlignment: CrossAxisAlignment.center,        mainAxisSize: MainAxisSize.min,        children: [          // ✅          if (item.status == 0) Icon(Icons.circle, color: Colors.grey[400], size: 23.h),          // ✅          if (item.status == 1) Icon(Icons.check_circle, color: Colors.green, size: 23.h),          // ❌          if (item.status == 2) Icon(Icons.cancel, color: Colors.red, size: 23.h),          const SizedBox(width: 10),          Text(item.title??"", style: titleStyles[item.status!]),        ],      ),    );  }}